#include "emoji_helper.hpp"
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("usage shaders rgba newout");std::ifstream f(argv[2],std::ios::binary|std::ios::ate);if(!f||f.tellg()!=12740*4)throw std::runtime_error("input size");std::vector<float>p(12740);f.seekg(0);f.read((char*)p.data(),p.size()*4);for(size_t i=0;i<p.size();i++)if(!std::isfinite(p[i])||p[i]<0||p[i]>1||(i%4!=3&&p[i]>p[i-i%4+3]))throw std::runtime_error("premult input range");std::filesystem::path out=argv[3];if(!std::filesystem::create_directory(out))throw std::runtime_error("existing output");{TextLab v(argv[1]);if(!v.validation)throw std::runtime_error("validation required");auto r=v.draw(p,{.1f,.2f,.3f,.5f},{0,0,0,0});save(out/"color.rgba32f",r[0]);save(out/"velocity.rgba32f",r[1]);save(out/"id.rgba32f",r[2]);std::cout<<"validation_enabled=1\n";}if(validationErrors)throw std::runtime_error("validation");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
